/*
 * magnification-small. It draws itself in, then its window becomes magnification-large's: the outline flows into the other drawing's,
 * holds, and flows back. Bring the pointer near and it turns toward the other.
 * Generated by dogfood/hard/generate.py from the owner's story (dogfood/HARD.md); measured, not read off by eye.
 */
const { icon, spring, stepS, register, pointer, disposer, story, clamp, smooth, SPRING } = IF;

function mount({ stage, svg, read, src }, reach) {
  const bag = disposer();
  const ic = icon(svg, src);
  const [opening] = ic.hole(0);
  const front = ic.part("front", [0], { paint: "first" });
  ic.part("side", [2]);
  const win = ic.part("window", [opening, 1]);
  win.hi(true);
  const S = front.extent("u-up"), W = win.extent("u-up");
  /* magnification-large's window, as fractions of its own screen (measured with the kernel), placed on this screen */
  const OTHER = [[0.7501, 0.375], [0.7474, 0.3536], [0.7363, 0.3312], [0.7186, 0.3166], [0.7014, 0.3125], [0.6855, 0.3125], [0.6697, 0.3125], [0.6538, 0.3125], [0.6379, 0.3125], [0.622, 0.3125], [0.6061, 0.3125], [0.5902, 0.3125], [0.5744, 0.3125], [0.5585, 0.3125], [0.5426, 0.3125], [0.5267, 0.3125], [0.5108, 0.3125], [0.4949, 0.3125], [0.479, 0.3125], [0.4632, 0.3125], [0.4473, 0.3125], [0.4314, 0.3125], [0.4155, 0.3125], [0.3996, 0.3125], [0.3837, 0.3125], [0.3679, 0.3125], [0.352, 0.3125], [0.3361, 0.3125], [0.3202, 0.3125], [0.3043, 0.3125], [0.2884, 0.3125], [0.2725, 0.3125], [0.2567, 0.3125], [0.2408, 0.3125], [0.2249, 0.3125], [0.209, 0.3125], [0.1933, 0.313], [0.1796, 0.3175], [0.1683, 0.3261], [0.1593, 0.3379], [0.153, 0.3527], [0.1501, 0.3705], [0.15, 0.3905], [0.15, 0.4104], [0.15, 0.4304], [0.15, 0.4504], [0.15, 0.4704], [0.15, 0.4903], [0.15, 0.5103], [0.15, 0.5303], [0.15, 0.5503], [0.15, 0.5703], [0.15, 0.5902], [0.15, 0.6102], [0.15, 0.6302], [0.15, 0.6502], [0.15, 0.6701], [0.15, 0.6901], [0.15, 0.7101], [0.15, 0.7301], [0.15, 0.7501], [0.1527, 0.7714], [0.1638, 0.7938], [0.1815, 0.8085], [0.1986, 0.8125], [0.2145, 0.8125], [0.2304, 0.8125], [0.2463, 0.8125], [0.2622, 0.8124], [0.278, 0.8124], [0.2939, 0.8124], [0.3098, 0.8124], [0.3257, 0.8124], [0.3416, 0.8125], [0.3575, 0.8125], [0.3734, 0.8125], [0.3893, 0.8125], [0.4051, 0.8125], [0.421, 0.8125], [0.4369, 0.8125], [0.4528, 0.8125], [0.4687, 0.8125], [0.4846, 0.8125], [0.5005, 0.8125], [0.5163, 0.8125], [0.5322, 0.8125], [0.5481, 0.8125], [0.564, 0.8125], [0.5799, 0.8125], [0.5958, 0.8125], [0.6116, 0.8125], [0.6275, 0.8125], [0.6434, 0.8125], [0.6593, 0.8125], [0.6752, 0.8125], [0.6911, 0.8125], [0.7068, 0.812], [0.7205, 0.8075], [0.7318, 0.7989], [0.7408, 0.7872], [0.7471, 0.7724], [0.75, 0.7545], [0.7501, 0.7346], [0.7501, 0.7146], [0.7501, 0.6946], [0.7501, 0.6747], [0.7501, 0.6547], [0.7501, 0.6347], [0.7501, 0.6147], [0.7501, 0.5948], [0.7501, 0.5748], [0.7501, 0.5548], [0.7501, 0.5348], [0.7501, 0.5148], [0.7501, 0.4949], [0.7501, 0.4749], [0.7501, 0.4549], [0.7501, 0.4349], [0.7501, 0.415], [0.7501, 0.395]];
  const target = OTHER.map(([fa, fb]) => S.pt(S.a[0] + fa * (S.a[1] - S.a[0]), S.b[0] + fb * (S.b[1] - S.b[0])));
  const shape = ic.morph(opening, target, { hide: [1] }); // its inner wall belongs to its own outline
  const life = story(stage, {
    rest: { become: 0, ink: 1 },
    poster: { become: 1, ink: 1 },
    intro: { dur: 3000, from: { ink: 0 }, ease: "linear" },
    beats: [
      { dur: 1000 },
      { dur: 900, to: { become: 1 } },  // it becomes the other
      { dur: 1500 },
      { dur: 900, to: { become: 0 } },  // and itself again
      { dur: 900 },
    ],
  });
  const hand = spring(0, SPRING.hand);
  let max = reach, label = "";
  const centre = W.pt((W.a[0] + W.a[1]) / 2, (W.b[0] + W.b[1]) / 2);
  const loop = register(stage, (dt) => {
    const x = life.step(dt), y = stepS(hand, dt);
    const v = life.values(life.held ? { become: hand.x } : {});
    ic.ink(v.ink);
    const t = v.become * max;
    shape.set(t);
    const shown = v.ink < 1 ? "drawing" : t < 0.02 ? "rest" : `large ${Math.round(t * 100)}%`;
    if (shown !== label) { read.textContent = shown; label = shown; }
    return x || y;
  });
  const leave = () => { life.hold(false); loop.wake(); };
  bag.add(pointer(stage, {
    move(pt) {
      const near = 1 - smooth(30, 170, Math.hypot(pt[0] - centre[0], pt[1] - centre[1]));
      if (near <= 0) { leave(); return; }
      if (!life.held) { hand.x = life.values().become; life.hold(true); }
      hand.t = near;
      loop.wake();
    },
    leave,
  }));
  bag.add(() => { loop.unregister(); while (svg.firstChild) svg.firstChild.remove(); });
  return { set(v) { max = clamp(v, 0, 1); loop.wake(); }, destroy: bag.dispose };
}

isoform({
  name: "magnification-small",
  icon: "magnification-small",
  variant: "rounded-left",
  means: "Its window flows into magnification-large's outline, holds, and flows back.",
  rules: [5, 8, 9],
  range: [0.6, 0.85, 1],
  mount,
});
